import { expect, test, uniqueName } from "../../fixtures";

test.describe("manage vendors", () => {
  test("update a draft vendor", { tag: "@VEN-08" }, async ({ apiAs }) => {
    // Arrange: a draft vendor owned by the member's tenant
    const member = await apiAs("member");
    const created = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Acme Freight"),
        category: "logistics",
        contact_email: `ops-${Date.now().toString(36)}@acme-freight.example`,
      },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = await created.json();
    expect(vendor.status).toBe("draft");

    // Act
    const newEmail = "billing@acmefreight.example";
    const response = await member.patch(`/api/vendors/${vendor.id}`, {
      data: { contact_email: newEmail },
    });

    // Assert
    expect(response.status(), await response.text()).toBe(200);
    const updated = await response.json();
    expect(updated.contact_email).toBe(newEmail);
    expect(updated.id).toBe(vendor.id);

    await expect
      .poll(async () => {
        const trail = await member.get(`/api/vendors/${vendor.id}/audit`);
        expect(trail.status(), await trail.text()).toBe(200);
        const body = (await trail.json()) as { items: { action: string }[] };
        return body.items.map((event) => event.action);
      })
      .toContain("vendor.updated");
  });
});
